def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
import os,re,json
G=load(); print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    blocks=[]
    for r in range(h-2):
        for c in range(w-2):
            col=g[r][c]
            if col and all(g[r+i][c+j]==col for i in range(3) for j in range(3)):
                blocks.append((r+1,c+1,col))
    out=[row[:] for row in g]
    for r,c,col in blocks:
        for j in range(w): out[r][j]=col
        for i in range(h): out[i][c]=col
    hs=[(r,col) for r,c,col in blocks]; vs=[(c,col) for r,c,col in blocks]
    for r,a in hs:
        for c,b in vs:
            if a!=b: out[r][c]=0
    return out
